import{_ as n,o as r,c as t,a3 as i}from"./chunks/framework.B5WAEDB7.js";const m=JSON.parse('{"title":"Formular teilen","description":"Formulare per Link, QR-Code oder eingebettet auf der eigenen Website bereitstellen.","frontmatter":{"title":"Formular teilen","description":"Formulare per Link, QR-Code oder eingebettet auf der eigenen Website bereitstellen."},"headers":[],"relativePath":"formulare/formular-teilen.md","filePath":"formulare/formular-teilen.md","lastUpdated":1786170655000}'),a={name:"formulare/formular-teilen.md"};function s(l,e,o,d,u,h){return r(),t("div",null,[...e[0]||(e[0]=[i('<h1 id="formular-teilen" tabindex="-1">Formular teilen <a class="header-anchor" href="#formular-teilen" aria-label="Permalink to &quot;Formular teilen&quot;">​</a></h1><p>Ein Formular ist erst erreichbar, wenn Sie einen Freigabelink erzeugen. Bis dahin existiert es nur im Editor.</p><h2 id="link-erzeugen" tabindex="-1">Link erzeugen <a class="header-anchor" href="#link-erzeugen" aria-label="Permalink to &quot;Link erzeugen&quot;">​</a></h2><p>Klicken Sie im Formular-Editor auf <strong>Link erstellen</strong>.</p><p>Es öffnet sich der Dialog <em>Teilen deines Formulars</em> mit dem Hinweis, dass das Formular sicher veröffentlicht wurde. Der Dialog hat drei Reiter: <strong>Link</strong>, <strong>QR-Code</strong> und <strong>In App öffnen</strong>.</p><div class="danger custom-block"><p class="custom-block-title">Ein Freigabelink ist standardmäßig öffentlich</p><p>Ohne zusätzliche Beschränkung kann <strong>jede Person mit dem Link</strong> das Formular öffnen und absenden. Der Link ist nicht erratbar, aber auch nicht geschützt — wird er weitergeleitet, funktioniert er weiter.</p><p>Bevor Sie einen Link verteilen, entscheiden Sie über <strong>Beschränkungen festlegen</strong>, wer zugreifen darf. Siehe <a href="/zusammenarbeit/zugriff-beschraenken">Zugriff auf geteilte Inhalte</a>.</p></div><h2 id="reiter-„link" tabindex="-1">Reiter „Link&quot; <a class="header-anchor" href="#reiter-„link" aria-label="Permalink to &quot;Reiter „Link&quot;&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Schaltfläche</th><th>Funktion</th></tr></thead><tbody><tr><td><strong>Kopieren</strong></td><td>Legt den Link in die Zwischenablage</td></tr><tr><td><strong>Vorschau in neuem Tab</strong></td><td>Öffnet das Formular so, wie Ausfüllende es sehen</td></tr><tr><td><strong>Beschränkungen festlegen</strong></td><td>Legt fest, wer zugreifen darf</td></tr><tr><td><strong>Formular vorausgefüllt teilen</strong></td><td>Erzeugt einen Link mit vorbelegten Werten</td></tr><tr><td><strong>Link hinzufügen</strong></td><td>Legt einen weiteren, eigenständigen Link an</td></tr></tbody></table><h3 id="mehrere-links-auf-dasselbe-formular" tabindex="-1">Mehrere Links auf dasselbe Formular <a class="header-anchor" href="#mehrere-links-auf-dasselbe-formular" aria-label="Permalink to &quot;Mehrere Links auf dasselbe Formular&quot;">​</a></h3><p>Über <strong>Link hinzufügen</strong> erzeugen Sie mehrere benannte Links auf dasselbe Formular. Der Dialog <em>Neuer Link</em> fragt nach einem Namen.</p><div class="tip custom-block"><p class="custom-block-title">Wofür mehrere Links nützlich sind</p><p>Jeder Link lässt sich einzeln benennen, beschränken und wieder entfernen. Damit können Sie Kanäle trennen: ein Link für den Newsletter, einer für die Website, einer für einen Messestand. Läuft eine Aktion aus, entfernen Sie nur diesen einen Link — die anderen bleiben gültig.</p><p>Wie viele zusätzliche Links möglich sind, hängt vom Tarif ab.</p></div><p>Alle Links eines Space sind gesammelt unter <a href="/zusammenarbeit/externe-links">Externe Links im Überblick</a> sichtbar.</p><h2 id="reiter-„qr-code" tabindex="-1">Reiter „QR-Code&quot; <a class="header-anchor" href="#reiter-„qr-code" aria-label="Permalink to &quot;Reiter „QR-Code&quot;&quot;">​</a></h2><p>Der QR-Code führt direkt zum Formular. Der Dialog erklärt: <em>Scanne diesen QR-Code mit der Kamera deines Smartphones, um das Formular direkt zu öffnen.</em></p><p>Gestaltbar sind:</p><ul><li><strong>Stil</strong> — <em>Kästchen</em>, <em>Punkte</em> oder <em>Rund</em></li><li><strong>Farbe</strong></li></ul><p>Herunterladen können Sie den Code als <strong>PNG</strong> oder <strong>SVG</strong>.</p><div class="tip custom-block"><p class="custom-block-title">PNG oder SVG?</p><p>Für Bildschirm und E-Mail genügt PNG. Für Druck — Plakate, Aufsteller, Verpackungen — nehmen Sie SVG: das Format bleibt bei jeder Größe scharf.</p><p>Der SVG-Download ist tarifabhängig.</p></div><div class="warning custom-block"><p class="custom-block-title">QR-Codes auf gedrucktem Material</p><p>Ein gedruckter QR-Code lässt sich nicht zurückrufen. Löschen Sie das Formular oder den Link, führt der Code ins Leere. Verwenden Sie für gedrucktes Material einen eigenen, benannten Link, den Sie dauerhaft bestehen lassen.</p></div><h2 id="reiter-„in-app-offnen" tabindex="-1">Reiter „In App öffnen&quot; <a class="header-anchor" href="#reiter-„in-app-offnen" aria-label="Permalink to &quot;Reiter „In App öffnen&quot;&quot;">​</a></h2><p>Zeigt einen QR-Code, mit dem sich das Formular in der mobilen App hinzufügen lässt, samt Verweisen auf App Store und Google Play.</p><h2 id="auf-der-eigenen-website-einbinden" tabindex="-1">Auf der eigenen Website einbinden <a class="header-anchor" href="#auf-der-eigenen-website-einbinden" aria-label="Permalink to &quot;Auf der eigenen Website einbinden&quot;">​</a></h2><p>Über <strong>Auf Ihrer Webseite einbinden</strong> erzeugen Sie den Einbettungscode.</p><p>Einstellungen:</p><ul><li><strong>Höhe automatisch anpassen</strong> — die Höhe folgt dem Formularinhalt</li><li><strong>Vorschau Smartphone</strong> und <strong>Vorschau Computer</strong> — Kontrolle vor dem Einbau</li></ul><p>Den fertigen Code finden Sie unter <em>Embed code</em>. Kopieren Sie ihn in Ihre Website.</p><div class="tip custom-block"><p class="custom-block-title">Höhe automatisch anpassen aktivieren</p><p>Ohne diese Option bekommt das eingebettete Formular eine feste Höhe. Bei mehrseitigen Formularen oder aufklappenden Feldern entsteht dann ein Scrollbalken innerhalb des Rahmens — unschön und auf Mobilgeräten schlecht bedienbar.</p></div><h2 id="vorausgefullte-links" tabindex="-1">Vorausgefüllte Links <a class="header-anchor" href="#vorausgefullte-links" aria-label="Permalink to &quot;Vorausgefüllte Links&quot;">​</a></h2><p><strong>Formular vorausgefüllt teilen</strong> öffnet einen Editor, in dem Sie das Formular selbst ausfüllen. Aus den eingetragenen Werten entsteht ein Link, der das Formular bereits befüllt öffnet.</p><p>Der Dialog erklärt: <em>Geben Sie bitte die Daten in die entsprechenden Formularfelder ein. Kopieren Sie den generierten Link und nutzen Sie ihn, um das Formular mit den vorausgefüllten Daten schnell und einfach zu teilen.</em></p><p>Typische Anwendungen:</p><ul><li>Kampagnen auseinanderhalten (verstecktes Feld <em>Quelle</em>)</li><li>Wiederkehrende Angaben vorbelegen (Standort, Abteilung, Veranstaltung)</li><li>Einen Flow mit festen Werten starten</li></ul><p>→ <a href="/formulare/vorausgefuellte-links">Vorausgefüllte Links</a></p><h2 id="einen-einzelnen-eintrag-zur-bearbeitung-teilen" tabindex="-1">Einen einzelnen Eintrag zur Bearbeitung teilen <a class="header-anchor" href="#einen-einzelnen-eintrag-zur-bearbeitung-teilen" aria-label="Permalink to &quot;Einen einzelnen Eintrag zur Bearbeitung teilen&quot;">​</a></h2><p>Neben dem Anlegen neuer Einträge können Formulare auch <strong>bestehende Einträge</strong> bearbeitbar machen. Den Link dazu erzeugen Sie nicht hier, sondern am Eintrag selbst über <strong>Eintrag teilen</strong>.</p><p>Voraussetzung ist ein passendes Formular — ohne Formular erscheint der Hinweis, dass Sie zuerst eines anlegen müssen.</p><p>→ <a href="/formulare/eintraege-bearbeiten">Einträge per Formular bearbeiten</a></p><h2 id="link-entfernen" tabindex="-1">Link entfernen <a class="header-anchor" href="#link-entfernen" aria-label="Permalink to &quot;Link entfernen&quot;">​</a></h2><p>Einen Link entfernen Sie im Freigabedialog oder über die <a href="/zusammenarbeit/externe-links">Links-Übersicht</a> des Space.</p><div class="warning custom-block"><p class="custom-block-title">Entfernen wirkt sofort</p><p>Ein entfernter Link funktioniert ab sofort nicht mehr — auch nicht für Personen, die ihn gespeichert oder gerade geöffnet haben. Bereits eingegangene Einträge bleiben selbstverständlich erhalten.</p></div><h2 id="wenn-ein-formular-nicht-erreichbar-ist" tabindex="-1">Wenn ein Formular nicht erreichbar ist <a class="header-anchor" href="#wenn-ein-formular-nicht-erreichbar-ist" aria-label="Permalink to &quot;Wenn ein Formular nicht erreichbar ist&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Meldung</th><th>Bedeutung</th></tr></thead><tbody><tr><td><em>Zugriff auf dieses Formular ist eingeschränkt.</em></td><td>Es gilt eine Zugriffsbeschränkung, die diese Person nicht erfüllt</td></tr><tr><td><em>Warnung: Potenziell riskantes Formular</em></td><td>Das Formular wurde als möglicherweise missbräuchlich eingestuft</td></tr><tr><td><em>Dieses Formular ist gesperrt</em></td><td>Das Formular wurde gesperrt</td></tr></tbody></table><p>Bei den letzten beiden wenden Sie sich an <code>abuse@apptivegrid.com</code>, wenn Sie eine Überprüfung beantragen möchten.</p><h2 id="weiter" tabindex="-1">Weiter <a class="header-anchor" href="#weiter" aria-label="Permalink to &quot;Weiter&quot;">​</a></h2><ul><li><a href="/zusammenarbeit/zugriff-beschraenken">Zugriff auf geteilte Inhalte</a></li><li><a href="/formulare/vorausgefuellte-links">Vorausgefüllte Links</a></li><li><a href="/zusammenarbeit/externe-links">Externe Links im Überblick</a></li></ul>',45)])])}const f=n(a,[["render",s]]);export{m as __pageData,f as default};
